// client/src/api/couponApi.js (최종 수정)

import axiosInstance from './axiosInstance'; 
const COUPON_URL = '/coupons'; // 백엔드 라우트 경로를 '/api/coupons'로 가정

// 1. 사용자 쿠폰 목록 가져오기
export const getMyCoupons = async () => {
    try {
        const response = await axiosInstance.get(COUPON_URL);
        // 서버가 데이터만 배열로 응답한다고 가정합니다.
        return response.data;
    } catch (error) {
        throw error.response?.data?.message || '쿠폰 목록 조회 실패';
    }
};

// 2. 쿠폰 사용 처리
export const redeemCoupon = async (couponId) => {
    try {
        // 서버의 엔드포인트를 POST /coupons/:id/redeem 으로 가정합니다.
        const response = await axiosInstance.post(`${COUPON_URL}/${couponId}/redeem`);
        
        // 서버는 사용 처리된 쿠폰 객체를 응답으로 돌려준다고 가정합니다.
        return response.data; 
    } catch (error) {
        throw error.response?.data || error.message; 
    }
};

// 3. 🚨 룰렛 보상 목록 가져오기 (CouponCenter.jsx에서 사용)
export const fetchRouletteRewards = async () => {
    try {
        // 서버의 엔드포인트를 GET /coupons/rewards 로 가정합니다.
        const response = await axiosInstance.get(`${COUPON_URL}/rewards`);
        return response.data; 
    } catch (error) {
        throw error.response?.data?.message || '룰렛 보상 목록 조회 실패';
    }
};

// 4. 🚨 룰렛 스핀 요청 (CouponCenter.jsx에서 사용)
export const spinRoulette = async () => {
    try {
        // 서버의 엔드포인트를 POST /coupons/spin 로 가정합니다.
        const response = await axiosInstance.post(`${COUPON_URL}/spin`);
        // 서버는 당첨 결과 객체(reward, coupon 등)를 응답으로 돌려준다고 가정합니다.
        return response.data; 
    } catch (error) {
        throw error.response?.data || error.message;
    }
};

// 🚨 모든 함수를 export default로 묶지 않고 개별 export로 제공하는 구조로 유지합니다.
// const couponApi = { getMyCoupons, redeemCoupon, fetchRouletteRewards, spinRoulette };
// export default couponApi; 
// (axiosInstance를 직접 import 했으므로, 이렇게 개별 export하는 것이 일반적입니다.)

// 파일 구조의 일관성을 위해, 필요하다면 아래와 같이 default export를 추가할 수 있습니다.
const couponApi = { getMyCoupons, redeemCoupon, fetchRouletteRewards, spinRoulette };
export default couponApi;
